/* eslint-disable no-restricted-globals -- an integration spec runs inside a live Zotero (docs/13 §2.3) and sets up and inspects the platform's own full-text state; there is no src/zotero/ facade to go through from outside the plugin bundle. */
/**
 * `P3-T18`: text acquisition tiers 1–2 against real Zotero.
 *
 * ## Fixtures
 *
 * Every PDF here is **generated by this file** — a few pages of Helvetica
 * text with a marker per page (`RHP3T18-PAGE-03-OF-05`) — written to Zotero's
 * temp directory and imported as a stored attachment. No paper is
 * downloaded or committed. The password-protected fixture is the same
 * generator with a standard-security-handler `/Encrypt` dictionary whose
 * `/U` entry does not match the empty password, which is exactly the state
 * pdf.js reports as `PasswordException` ("a password is needed").
 *
 * ## How the index states are reached
 *
 * Zotero's own import path queues every new attachment for background
 * indexing (`Zotero.FullText.queueItem`, five seconds after the last import).
 * The spec waits for that rather than indexing anything itself, and sets
 * `extensions.zotero.fulltext.pdfMaxPages` to 2 **before** importing the
 * five-page file so that Zotero's own indexer leaves it
 * `INDEX_STATE_PARTIAL`. Only if the queue has not finished within
 * {@link INDEX_WAIT_MS} does it call `Zotero.Fulltext.indexItems` itself —
 * a test-setup step, never something `src/` does — and it prints which path
 * was taken.
 *
 * ## Counting PDFWorker calls
 *
 * `Zotero.PDFWorker.getFullText` is wrapped for the duration of each
 * acquisition and every call is recorded with its `itemID` and `maxPages`.
 * Only calls for the attachment under test are asserted on, so a background
 * index of some other item cannot make a count wrong.
 *
 * Everything created is erased; the temp files are removed; both preferences
 * are restored.
 */

import { config } from "../../../package.json";
import { setPrefStore, setPref, clearPref } from "../../../src/prefs";
import { acquireZoteroSource } from "../../../src/pipeline/summarize/acquire";
import {
  getIndexedPageCounts,
  getIndexedState,
  pickTextAttachment,
} from "../../../src/zotero/fulltext";
import { createZoteroPrefStore } from "../../../src/zotero/prefStore";
import { sha256Hex } from "../../support/sha256";

// Mocha and Chai globals injected by the scaffold runner's index.xhtml. Typed
// locally, to exactly what this file uses: no Mocha types are installed.
interface MochaContext {
  timeout(ms: number): void;
}
declare function describe(title: string, body: () => void): void;
declare function it(
  title: string,
  body: (this: MochaContext) => Promise<void>,
): void;
declare function after(body: () => Promise<void>): void;
declare const assert: {
  strictEqual<T>(actual: T, expected: T, message?: string): void;
  notStrictEqual<T>(actual: T, expected: T, message?: string): void;
  deepEqual<T>(actual: T, expected: T, message?: string): void;
  isTrue(value: boolean, message?: string): void;
  isFalse(value: boolean, message?: string): void;
  include(
    haystack: readonly unknown[] | string,
    needle: unknown,
    message?: string,
  ): void;
  notInclude(
    haystack: readonly unknown[] | string,
    needle: unknown,
    message?: string,
  ): void;
  fail(message: string): never;
};
/** The scaffold runner's `window.debug`: POSTs one line to the terminal. */
declare function debug(line: string): void;

const LOG = "[P3-T18]";
const TEST_TIMEOUT_MS = 90_000;
const INDEX_WAIT_MS = 30_000;
const PDF_MAX_PAGES_PREF = "fulltext.pdfMaxPages";

/** Over `summary.minAbstractChars`' default of 250. Written for this spec. */
const ABSTRACT =
  "BACKGROUND: Synthetic widgets were studied at three invented field sites. " +
  "METHODS: Widgets were counted weekly for one simulated year by two observers. " +
  "RESULTS: Counts rose by 4% between the first and last quarter. " +
  "CONCLUSIONS: Widgets are countable, and the counts are stable between observers.";

// ---------------------------------------------------------------------------
// The synthetic PDF generator
// ---------------------------------------------------------------------------

function pageMarker(page: number, total: number): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return `RHP3T18-PAGE-${pad(page)}-OF-${pad(total)}`;
}

/**
 * A minimal, valid PDF 1.4 with `pageCount` text pages. ASCII only, so the
 * string's length is its byte length and the xref offsets are exact.
 */
function makePdf(
  pageCount: number,
  options: { encrypted?: boolean } = {},
): Uint8Array {
  const objects: string[] = [];
  const add = (body: string): number => {
    objects.push(body);
    return objects.length;
  };
  const catalog = add("");
  const pages = add("");
  const font = add("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
  const kids: number[] = [];
  for (let page = 1; page <= pageCount; page += 1) {
    const lines = [
      pageMarker(page, pageCount),
      `Synthetic fixture text for page ${page} of ${pageCount}.`,
      "This line is generated by the P3-T18 integration spec.",
    ];
    const ops = lines
      .map((line, i) => `${i === 0 ? "72 720 Td" : "0 -16 Td"} (${line}) Tj`)
      .join("\n");
    const stream = `BT /F1 12 Tf\n${ops}\nET`;
    const contents = add(
      `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
    );
    kids.push(
      add(
        `<< /Type /Page /Parent ${pages} 0 R /MediaBox [0 0 612 792] ` +
          `/Resources << /Font << /F1 ${font} 0 R >> >> /Contents ${contents} 0 R >>`,
      ),
    );
  }
  objects[catalog - 1] = `<< /Type /Catalog /Pages ${pages} 0 R >>`;
  objects[pages - 1] =
    `<< /Type /Pages /Kids [${kids.map((k) => `${k} 0 R`).join(" ")}] /Count ${pageCount} >>`;
  let encryptRef = "";
  if (options.encrypted === true) {
    const junk = "A5".repeat(32);
    const encrypt = add(
      `<< /Filter /Standard /V 1 /R 2 /O <${junk}> /U <${"5A".repeat(32)}> /P -44 >>`,
    );
    encryptRef = ` /Encrypt ${encrypt} 0 R /ID [<${"0123456789ABCDEF".repeat(2)}> <${"FEDCBA9876543210".repeat(2)}>]`;
  }

  let out = "%PDF-1.4\n";
  const offsets: number[] = [];
  objects.forEach((body, i) => {
    offsets.push(out.length);
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xrefAt = out.length;
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  for (const offset of offsets) {
    out += `${String(offset).padStart(10, "0")} 00000 n \n`;
  }
  out += `trailer\n<< /Size ${objects.length + 1} /Root ${catalog} 0 R${encryptRef} >>\nstartxref\n${xrefAt}\n%%EOF\n`;
  return new TextEncoder().encode(out);
}

// ---------------------------------------------------------------------------
// Platform helpers
// ---------------------------------------------------------------------------

const created: Zotero.Item[] = [];
const tempFiles: string[] = [];

async function createParent(abstract: string): Promise<Zotero.Item> {
  const item = new Zotero.Item("journalArticle");
  item.setField("title", `P3-T18 acquisition fixture ${Date.now()}`);
  item.setField("abstractNote", abstract);
  await item.saveTx();
  created.push(item);
  return item;
}

async function attachPdf(
  parent: Zotero.Item,
  bytes: Uint8Array,
  name: string,
): Promise<Zotero.Item> {
  const path = PathUtils.join(
    Zotero.getTempDirectory().path,
    `rh-p3t18-${name}-${Date.now()}.pdf`,
  );
  await IOUtils.write(path, bytes);
  tempFiles.push(path);
  const attachment = await Zotero.Attachments.importFromFile({
    file: path,
    parentItemID: parent.id,
    contentType: "application/pdf",
  });
  return attachment;
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Wait for Zotero's background indexer to reach `wanted`; index directly as a
 * last resort. Returns how the state was reached.
 */
async function waitForIndexState(
  attachment: Zotero.Item,
  wanted: number,
): Promise<"background" | "direct"> {
  const deadline = Date.now() + INDEX_WAIT_MS;
  while (Date.now() < deadline) {
    if ((await Zotero.Fulltext.getIndexedState(attachment)) === wanted) {
      return "background";
    }
    await delay(250);
  }
  await Zotero.Fulltext.indexItems([attachment.id]);
  const state = await Zotero.Fulltext.getIndexedState(attachment);
  if (state !== wanted) {
    assert.fail(
      `index state ${state}, wanted ${wanted}, after direct indexing`,
    );
  }
  return "direct";
}

interface WorkerCall {
  readonly itemID: number;
  readonly maxPages: unknown;
}

type GetFullText = (
  itemID: number,
  maxPages?: number | null,
  isPriority?: boolean,
  password?: string,
) => Promise<unknown>;

/** Run `body` with every `PDFWorker.getFullText` call recorded. */
async function withWorkerSpy<T>(
  body: () => Promise<T>,
): Promise<{ result: T; calls: WorkerCall[] }> {
  const worker = Zotero.PDFWorker as { getFullText: GetFullText };
  const hadOwn = Object.prototype.hasOwnProperty.call(worker, "getFullText");
  const original = worker.getFullText;
  const calls: WorkerCall[] = [];
  worker.getFullText = function (this: unknown, itemID, maxPages, ...rest) {
    calls.push({ itemID, maxPages });
    return original.call(this, itemID, maxPages, ...rest);
  };
  try {
    return { result: await body(), calls };
  } finally {
    if (hadOwn) worker.getFullText = original;
    else delete (worker as Partial<typeof worker>).getFullText;
  }
}

const estimateTokens = (text: string): number => Math.ceil(text.length / 4);

function pagesPresent(text: string, total: number): number[] {
  const present: number[] = [];
  for (let page = 1; page <= total; page += 1) {
    if (text.includes(pageMarker(page, total))) present.push(page);
  }
  return present;
}

function count(text: string, needle: string): number {
  return text.split(needle).length - 1;
}

/**
 * Split the recorded calls for `attachmentID` into the ones acquisition can
 * have caused and the ones Zotero's own background indexers made.
 *
 * Zotero 10.0.3 has two background paths that extract a PDF on their own —
 * the new-attachment queue and the content-index queue, both through
 * `indexItems` → `indexPDF` — and both pass `maxPages` as the
 * `fulltext.pdfMaxPages` number. Acquisition can only cause `undefined`
 * (`attachmentText`'s on-demand rung), `null` (every page) or the attachment's
 * `indexedPages`. Run 2 of this spec on 2026-10-21 recorded one background
 * call for a fully indexed item during acquisition; run 1 recorded none.
 */
function attribute(
  calls: readonly WorkerCall[],
  attachmentID: number,
): { acquisition: WorkerCall[]; background: WorkerCall[] } {
  const indexerMaxPages = Zotero.Prefs.get(PDF_MAX_PAGES_PREF);
  const own = calls.filter((call) => call.itemID === attachmentID);
  const isBackground = (call: WorkerCall) =>
    typeof call.maxPages === "number" && call.maxPages === indexerMaxPages;
  return {
    acquisition: own.filter((call) => !isBackground(call)),
    background: own.filter(isBackground),
  };
}

after(async function () {
  setPrefStore(undefined);
  if (created.length > 0) {
    await Zotero.Items.erase(created.map((item) => item.id));
  }
  for (const path of tempFiles) {
    await IOUtils.remove(path, { ignoreAbsent: true });
  }
});

// ---------------------------------------------------------------------------
// The specs
// ---------------------------------------------------------------------------

describe("P3-T18 text acquisition tiers 1-2", function () {
  it("a fully indexed PDF yields Tier 2 text with zero PDFWorker calls", async function () {
    this.timeout(TEST_TIMEOUT_MS);
    const parent = await createParent(ABSTRACT);
    const attachment = await attachPdf(parent, makePdf(3), "indexed");
    const how = await waitForIndexState(
      attachment,
      Zotero.Fulltext.INDEX_STATE_INDEXED,
    );

    const picked = await pickTextAttachment(parent);
    assert.strictEqual(
      picked?.id,
      attachment.id,
      "pickTextAttachment chose the PDF",
    );

    const { result: source, calls } = await withWorkerSpy(() =>
      acquireZoteroSource(parent, { estimateTokens }),
    );
    const { acquisition, background } = attribute(calls, attachment.id);
    debug(
      `${LOG} indexed: reached ${how}; tier=${source.tier}; chars=${source.charCount}; ` +
        `acquisition calls=${JSON.stringify(acquisition)}; background indexer calls=${JSON.stringify(background)}; ` +
        `formFeeds=${count(source.text, "\f")}`,
    );
    assert.strictEqual(
      acquisition.length,
      0,
      "no PDFWorker call from acquisition for a fully indexed PDF",
    );
    assert.strictEqual(source.tier, "fulltext_pdf");
    assert.strictEqual(source.attachmentKey, attachment.key);
    assert.strictEqual(source.truncated, false);
    assert.deepEqual(pagesPresent(source.text, 3), [1, 2, 3]);
    assert.isTrue(
      source.text.startsWith(`${ABSTRACT}\n\n`),
      "abstract preamble",
    );
    assert.strictEqual(
      count(source.text, "\f"),
      2,
      "\\f appears totalPages - 1 times",
    );
    assert.deepEqual(source.warnings, []);
    assert.strictEqual(source.contentHash, sha256Hex(source.text));
  });

  it("INDEX_STATE_PARTIAL: one re-extraction under the cap; over it, the indexed pages only and truncated", async function () {
    this.timeout(TEST_TIMEOUT_MS * 2);
    setPrefStore(createZoteroPrefStore());
    const savedMaxPages = Zotero.Prefs.get(PDF_MAX_PAGES_PREF);
    let attachment: Zotero.Item;
    const parent = await createParent(ABSTRACT);
    try {
      Zotero.Prefs.set(PDF_MAX_PAGES_PREF, 2);
      attachment = await attachPdf(parent, makePdf(5), "partial");
      const how = await waitForIndexState(
        attachment,
        Zotero.Fulltext.INDEX_STATE_PARTIAL,
      );
      debug(`${LOG} partial: reached ${how}`);
    } finally {
      if (savedMaxPages === undefined) Zotero.Prefs.clear(PDF_MAX_PAGES_PREF);
      else Zotero.Prefs.set(PDF_MAX_PAGES_PREF, savedMaxPages);
    }
    const counts = await getIndexedPageCounts(attachment.id);
    assert.deepEqual(counts, { indexedPages: 2, total: 5 });

    // What attachmentText itself does in this state: the measurement behind
    // acquire.ts's D-06-3 note.
    const { result: raw, calls: rawCalls } = await withWorkerSpy(async () => {
      const text: unknown = await attachment.attachmentText;
      return typeof text === "string" ? text : "";
    });
    const rawOwn = rawCalls.filter((call) => call.itemID === attachment.id);
    debug(
      `${LOG} partial: attachmentText made ${rawOwn.length} PDFWorker call(s) ` +
        `(maxPages=${rawOwn.map((c) => String(c.maxPages)).join(",")}) and returned pages ` +
        `[${pagesPresent(raw, 5).join(",")}]`,
    );

    try {
      setPref("fullTextHardPageCap", 10);
      const under = await withWorkerSpy(() =>
        acquireZoteroSource(parent, { estimateTokens }),
      );
      const underSplit = attribute(under.calls, attachment.id);
      const underOwn = underSplit.acquisition;
      debug(
        `${LOG} partial under cap: calls=${JSON.stringify(underOwn)} background=${JSON.stringify(underSplit.background)} ` +
          `truncated=${String(under.result.truncated)} ` +
          `pages=[${pagesPresent(under.result.text, 5).join(",")}]`,
      );
      assert.strictEqual(
        underOwn.length,
        1,
        "exactly one re-extraction under the cap",
      );
      assert.strictEqual(
        underOwn[0]?.maxPages,
        null,
        "the re-extraction reads every page",
      );
      assert.strictEqual(under.result.truncated, false);
      assert.deepEqual(pagesPresent(under.result.text, 5), [1, 2, 3, 4, 5]);

      setPref("fullTextHardPageCap", 3);
      const over = await withWorkerSpy(() =>
        acquireZoteroSource(parent, { estimateTokens }),
      );
      const overSplit = attribute(over.calls, attachment.id);
      const overOwn = overSplit.acquisition;
      debug(
        `${LOG} partial over cap: calls=${JSON.stringify(overOwn)} background=${JSON.stringify(overSplit.background)} ` +
          `truncated=${String(over.result.truncated)} ` +
          `pages=[${pagesPresent(over.result.text, 5).join(",")}]`,
      );
      assert.strictEqual(
        overOwn.filter(
          (call) => call.maxPages === null || call.maxPages === undefined,
        ).length,
        0,
        "no all-pages re-extraction over the cap",
      );
      assert.deepEqual(
        overOwn.map((call) => call.maxPages),
        [2],
        "one bounded read of the indexed pages",
      );
      assert.strictEqual(over.result.truncated, true);
      assert.deepEqual(pagesPresent(over.result.text, 5), [1, 2]);
    } finally {
      clearPref("fullTextHardPageCap");
      setPrefStore(undefined);
    }
    assert.strictEqual(
      await getIndexedState(attachment),
      Zotero.Fulltext.INDEX_STATE_PARTIAL,
      "acquisition left the index as it found it",
    );
  });

  it("a password-protected PDF demotes to Tier 1 without throwing", async function () {
    this.timeout(TEST_TIMEOUT_MS);
    const parent = await createParent(ABSTRACT);
    const attachment = await attachPdf(
      parent,
      makePdf(2, { encrypted: true }),
      "password",
    );

    let measured = "(did not throw)";
    try {
      await Zotero.PDFWorker.getFullText(attachment.id, null);
    } catch (error) {
      const e = error as { name?: unknown; message?: unknown };
      measured = `name=${String(e.name)} message=${String(e.message).slice(0, 200)}`;
    }
    debug(`${LOG} password fixture, direct getFullText: ${measured}`);

    const source = await acquireZoteroSource(parent, { estimateTokens });
    debug(
      `${LOG} password: tier=${source.tier} warnings=${source.warnings.join(",")}`,
    );
    assert.strictEqual(source.tier, "abstract");
    assert.strictEqual(source.text, ABSTRACT);
    assert.strictEqual(source.attachmentKey, null);
    assert.include(source.warnings, "pdf_password_protected");
  });

  it("an attachment whose file is not on this computer demotes and downloads nothing", async function () {
    this.timeout(TEST_TIMEOUT_MS);
    const parent = await createParent(ABSTRACT);
    // `pdfMaxPages` 0 makes Zotero's own indexer write nothing (`indexPDF`
    // returns early), so no cache can stand in for the missing file.
    const savedMaxPages = Zotero.Prefs.get(PDF_MAX_PAGES_PREF);
    let attachment: Zotero.Item;
    let path: string;
    try {
      Zotero.Prefs.set(PDF_MAX_PAGES_PREF, 0);
      attachment = await attachPdf(parent, makePdf(2), "missing");
      const found = await attachment.getFilePathAsync();
      if (typeof found !== "string")
        assert.fail("the imported attachment has no path");
      path = found;
      const stateAtImport = await Zotero.Fulltext.getIndexedState(attachment);
      await IOUtils.remove(path);
      debug(
        `${LOG} missing file: state at import=${stateAtImport}; ` +
          `cache file exists=${String(Zotero.Fulltext.getItemCacheFile(attachment).exists())}; ` +
          `file exists after remove=${String(await IOUtils.exists(path))}; ` +
          `getFilePathAsync after remove=${String(await attachment.getFilePathAsync())}`,
      );
    } finally {
      if (savedMaxPages === undefined) Zotero.Prefs.clear(PDF_MAX_PAGES_PREF);
      else Zotero.Prefs.set(PDF_MAX_PAGES_PREF, savedMaxPages);
    }

    const text: unknown = await attachment.attachmentText.catch(
      (error: unknown) =>
        `threw ${String((error as { message?: unknown }).message).slice(0, 120)}`,
    );
    debug(`${LOG} missing file, attachmentText: ${JSON.stringify(text)}`);

    const source = await acquireZoteroSource(parent, { estimateTokens });
    debug(
      `${LOG} missing file: tier=${source.tier} warnings=${source.warnings.join(",")}`,
    );
    assert.strictEqual(source.tier, "abstract");
    assert.isTrue(
      source.warnings.includes("attachment_text_failed") ||
        source.warnings.includes("attachment_text_empty"),
      "a demotion warning",
    );
    assert.isFalse(await IOUtils.exists(path), "the file was not fetched back");
  });

  it("contentHash changes with the text and not with dateModified", async function () {
    this.timeout(TEST_TIMEOUT_MS);
    const parent = await createParent(ABSTRACT);
    const first = await acquireZoteroSource(parent, { estimateTokens });
    const modifiedBefore = parent.dateModified;

    await delay(1100); // dateModified has one-second resolution
    parent.setField("extra", `touched ${Date.now()}`);
    await parent.saveTx();
    const touched = await acquireZoteroSource(parent, { estimateTokens });

    parent.setField(
      "abstractNote",
      `${ABSTRACT} An added sentence changes the text.`,
    );
    await parent.saveTx();
    const changed = await acquireZoteroSource(parent, { estimateTokens });

    const sandbox = (
      Components.utils.getGlobalForObject as (o: unknown) => unknown
    )((Zotero as unknown as Record<string, unknown>)[config.addonInstance]) as
      { crypto?: { subtle?: { digest?: unknown } } } | undefined;
    debug(
      `${LOG} hash: dateModified ${modifiedBefore} -> ${parent.dateModified}; ` +
        `sandbox crypto.subtle.digest is ${typeof sandbox?.crypto?.subtle?.digest}; ` +
        `test-window crypto.subtle.digest is ${typeof (globalThis as { crypto?: { subtle?: { digest?: unknown } } }).crypto?.subtle?.digest}`,
    );
    assert.notStrictEqual(
      parent.dateModified,
      modifiedBefore,
      "dateModified moved",
    );
    assert.strictEqual(touched.contentHash, first.contentHash);
    assert.notStrictEqual(changed.contentHash, first.contentHash);
    assert.strictEqual(first.contentHash, sha256Hex(first.text));
    assert.notInclude(first.warnings, "content_hash_md5");
  });
});
